using System;using System.IO;using LoopFive;
class AudioQualityTests {
 static int count;static void A(bool ok,string text){if(!ok)throw new Exception(text);count++;Console.WriteLine("PASS "+text);}
 static Engine Clean(){Engine e=new Engine();e.Config.Master=1;e.Config.Limiter=false;e.Config.Gate=0;e.Config.Quantize=false;for(int i=0;i<5;i++){e.Tracks[i].Config.Level=1;e.Tracks[i].Config.LoopSync=false;}return e;}
 static void Main(){Directory.CreateDirectory("work/audio-quality");try{
  CaptureQueue q=new CaptureQueue(1024);short[] shortBlock={1,2,3,4};q.Push(shortBlock,4);float[] f=new float[1024];long[] ids=new long[512];f[0]=123;A(!q.TryRead(f,ids,512)&&q.Available==2&&f[0]==123,"partial capture waits without fabricating zeros or consuming input");
  q=new CaptureQueue(32);for(int i=0;i<200;i++){q.Push(new short[]{(short)i,(short)-i},2);ARead(q,i);}A(true,"capture ring wraps with exact stereo values and monotonic frame ids");
  q=new CaptureQueue(2);A(!q.Push(new short[6],6)&&q.OverflowFrames==3,"capture overflow is reported rather than silently truncating input");
  const int start=1000,recordLength=131072,total=133120;short[] pcm=new short[total*2];for(int i=0;i<total;i++){double t=i/44100.0;float gain=i>30000&&i<45000?.0007f:.35f;pcm[2*i]=(short)((Math.Sin(2*Math.PI*(110*t+35*t*t))*.7+Math.Sin(2*Math.PI*431*t)*.3)*gain*32767);pcm[2*i+1]=(short)(Math.Sin(2*Math.PI*279*t)*gain*32767);}
  Engine e=Clean();e.RequireRecordAcknowledgement=true;long boundary=start;e.FreshInputBoundary=delegate{return boundary;};e.Action(0);boundary=start+recordLength;e.Action(0);q=new CaptureQueue(8192);float[] input=new float[1024],output=new float[1024];Random random=new Random(504);int pushed=0,read=0;while(pushed<total){int n=Math.Min(total-pushed,random.Next(1,1537));short[] packet=new short[n*2];Array.Copy(pcm,pushed*2,packet,0,n*2);if(!q.Push(packet,packet.Length))throw new Exception("Unexpected overflow");pushed+=n;while(q.TryRead(input,ids,512)){e.Process(input,output,512,ids);read+=512;}}
  AudioClip clip=e.Tracks[0].Clip;A(clip!=null&&clip.Length==recordLength,"recorded take has exact requested capture duration despite packet jitter");double error=0;int quiet=0;for(int i=0;i<clip.Length;i++){float a=pcm[(i+start)*2]/32768f,b=pcm[(i+start)*2+1]/32768f;error=Math.Max(error,Math.Max(Math.Abs(a-clip.L[i]),Math.Abs(b-clip.R[i])));if(i+start>30000&&i+start<45000&&a!=0&&clip.L[i]!=0)quiet++;}A(error==0,"recorded stereo samples are bit-exact to decoded 16-bit source");A(quiet>10000,"quiet details are retained without noise-gate chopping");A(e.Tracks[0].AwaitingRecordVisible,"audio capture is independent of GUI paint acknowledgement");
  Wav.Write("work/audio-quality/recorded.wav",clip,true);AudioClip exported=Wav.Read("work/audio-quality/recorded.wav",120);A(exported.Length==clip.Length&&exported.L[10000]==clip.L[10000],"exported recording preserves source samples");
  e.Stop(0,true);e.Play(0);double square=0;int position=0;while(position<clip.Length){int n=Math.Min(512,clip.Length-position);e.Process(null,output,n);for(int i=0;i<n;i++){double delta=output[2*i]-clip.L[position+i];square+=delta*delta;}position+=n;}A(Math.Sqrt(square/clip.Length)<.000001,"clean playback matches recorded signal without audible processing error");
  e=Clean();e.Import(0,new AudioClip(new float[4096],new float[4096],120,1));e.Play(0);e.AutomaticLatencyFrames=512;e.Overdub(0);float[] pulse=new float[2]{.5f,.5f};e.Process(pulse,new float[2],1);A(Math.Abs(e.Tracks[0].Clip.L[4096-512]-.5f)<.00001,"automatic overdub offset writes at the earlier audible loop position");e.AutomaticLatencyFrames=999;e.Process(new float[]{.25f,.25f},new float[2],1);A(Math.Abs(e.Tracks[0].Clip.L[4096-511]-.25f)<.00001,"overdub offset remains fixed during take to avoid jitter and sample jumps");
  e=Clean();e.Config.Gate=.03f;e.Process(new float[]{.001f,.001f},new float[2],1);e.Action(0);e.Process(new float[]{.001f,.001f},new float[2],1);A(e.Tracks[0].RecordL[0]>0,"optional noise gate attenuates smoothly instead of hard-cutting quiet audio");
  e=Clean();e.Config.Gate=.01f;e.Config.InputFx.Slots[0].On=true;e.Config.Tracks[0].Speed=2;e.SetCleanRecording();A(e.Config.Gate==0&&!e.Config.InputFx.Enabled&&!e.Config.TrackFx.Enabled&&e.Config.Tracks[0].Speed==1,"clean recording preset bypasses FX, gating and pitch-changing speed");
  e=Clean();e.RequireRecordAcknowledgement=true;e.Tracks[0].Config.Level=0;using(NativeAudio native=new NativeAudio(e)){e.FreshInputBoundary=native.FreshCaptureBoundary;native.Start();System.Threading.Thread.Sleep(150);e.Action(0);long startFrame=e.Tracks[0].CaptureInputFloor;System.Threading.Thread.Sleep(1200);e.Action(0);long stopFrame=e.Tracks[0].CaptureStopInputId;for(int attempt=0;attempt<100&&e.Tracks[0].State==PlayState.Recording;attempt++)System.Threading.Thread.Sleep(10);A(e.Tracks[0].Clip!=null&&e.Tracks[0].Clip.Length==stopFrame-startFrame,"real Windows capture drains the final block and preserves exact start/stop frame interval");A(native.LastError==null&&native.OutputGaps==0,"real device capture/render remains continuous without output starvation during smoke test");e.Stop(0,true);native.Stop();}
  Console.WriteLine("TOTAL "+count+" audio fidelity checks passed; maximum capture sample error = 0");
 }catch(Exception ex){Console.WriteLine("FAIL "+ex);Environment.ExitCode=1;}}
 static void ARead(CaptureQueue q,int i){float[] a=new float[2];long[] id=new long[1];if(!q.TryRead(a,id,1)||id[0]!=i||a[0]!=i/32768f||a[1]!=-i/32768f)throw new Exception("Capture ring data changed");}
}
